// Queue message sent after checkpoint data is upserted into PlanetScale
export interface SearchIndexMessage {
  repoId: string
  checkpointIds: string[]
  queuedAt: string
  // Present when triggered by admin reindex — enables stateless progress logging
  reindexId?: string
  reindexMessageIndex?: number
  reindexTotalMessages?: number
}

// Type guard to check if a message is a SearchIndexMessage
export function isSearchIndexMessage(msg: unknown): msg is SearchIndexMessage {
  return (
    typeof msg === "object" &&
    msg !== null &&
    "repoId" in msg &&
    "checkpointIds" in msg &&
    "queuedAt" in msg &&
    typeof (msg as SearchIndexMessage).repoId === "string" &&
    Array.isArray((msg as SearchIndexMessage).checkpointIds)
  )
}

// Log with consistent prefix
function log(event: string, data: Record<string, unknown>): void {
  console.log(`[search-index-queue] ${event}`, JSON.stringify(data))
}

// Store a failed search index message after max retries exhausted (dead-letter).
// Stores in KV with 30-day TTL for later investigation and potential re-processing.
async function storeFailedSearchIndexMessage(
  cache: KVNamespace,
  message: SearchIndexMessage,
  error: unknown,
  attempts: number,
): Promise<void> {
  const id = crypto.randomUUID()
  const errorMessage = error instanceof Error ? error.message : String(error)

  const failureData = {
    id,
    repoId: message.repoId,
    checkpointIds: message.checkpointIds,
    reindexId: message.reindexId,
    error_message: errorMessage,
    attempts,
    failed_at: new Date().toISOString(),
    queued_at: message.queuedAt,
  }

  await cache.put(`search_index_dlq:${id}`, JSON.stringify(failureData), {
    expirationTtl: 60 * 60 * 24 * 30, // 30 days
  })

  log("dead_letter", {
    repoId: message.repoId,
    checkpointCount: message.checkpointIds.length,
    attempts,
    error: errorMessage.slice(0, 200),
  })
}

// Ensure transcripts are stored in DB, fetching from GitHub if needed.
