  const transcripts = new Map<string, string | null>()
  if (checkpoints.length === 0) return transcripts

  // 1. Try to load transcripts already stored in the DB (written at webhook time).
  const checkpointIds = checkpoints.map((cp) => cp.checkpoint_id)
  const dbRows = await db.checkpoints.getTranscriptBatch(repoId, checkpointIds)
  const missingCheckpoints: typeof checkpoints = []

  for (const row of dbRows) {
    if (row.transcript_stripped) {
      const sessions = parseStoredTranscriptSessions(row.transcript_stripped)
      if (sessions) {
        const primaryJsonl = sessions["0"]?.content
        transcripts.set(row.checkpoint_id, primaryJsonl ?? null)
      } else {
        // Corrupted DB entry — treat as missing so it gets re-fetched
        missingCheckpoints.push(checkpoints.find((cp) => cp.checkpoint_id === row.checkpoint_id)!)
      }
    } else {
      missingCheckpoints.push(checkpoints.find((cp) => cp.checkpoint_id === row.checkpoint_id)!)
    }
  }

  // Also include any checkpoint_ids not returned by the DB at all
  const returnedIds = new Set(dbRows.map((r) => r.checkpoint_id))
  for (const cp of checkpoints) {
    if (!returnedIds.has(cp.checkpoint_id) && !transcripts.has(cp.checkpoint_id)) {
      missingCheckpoints.push(cp)
    }
  }

  // 2. Fetch missing transcripts from GitHub as a fallback.
  if (missingCheckpoints.length > 0 && installationId) {
    try {
      const githubInstallationId = await db.installations.getGithubId(installationId)
      if (!githubInstallationId) {
        log("transcript_no_github_installation", { batchId, repoId, installationId })
        return transcripts
      }

      const token = await getInstallationToken(
        githubInstallationId,
        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
        env.ENTIRE_CACHE,
      )

      const dbUpdates: Array<{
        checkpoint_id: string
        transcript_stripped: string
        deadSessionIndices?: number[]
      }> = []
      const deadOnlyUpdates: Array<{ checkpoint_id: string; deadSessionIndices: number[] }> = []
      const repoProvider = await pickRepoReadProvider(env, repoFullName)

      for (let i = 0; i < missingCheckpoints.length; i += TRANSCRIPT_CONCURRENCY) {
        const transcriptBatch = missingCheckpoints.slice(i, i + TRANSCRIPT_CONCURRENCY)
        const results = await Promise.all(
          transcriptBatch.map((cp) =>
            fetchAndStripTranscripts(
              repoProvider,
              repoFullName,
              cp.checkpoint_id,
              cp.session_count ?? 1,
              cp.agent,
              (cp.sessions as SessionInfo[] | null) ?? null,
              cp.storage_version,
              token,
            ),
          ),
        )

        for (let j = 0; j < results.length; j++) {
          const cp = transcriptBatch[j]
          const result = results[j]
          if (!result) continue
          const { sessions, hadTransientError } = result
          const sessionCount = cp.session_count ?? 1
          const hasContent = Object.keys(sessions).length > 0
          const deadIndices = hadTransientError
            ? undefined
            : computeDeadSessionIndices(sessionCount, sessions)
          if (hasContent) {
            dbUpdates.push({
              checkpoint_id: cp.checkpoint_id,
              transcript_stripped: serializeStoredTranscriptSessions(sessions),
              deadSessionIndices: deadIndices,
            })

            const primaryJsonl = sessions["0"]?.content
            transcripts.set(cp.checkpoint_id, primaryJsonl ?? null)
          } else if (deadIndices && deadIndices.length > 0) {
            deadOnlyUpdates.push({
              checkpoint_id: cp.checkpoint_id,
              deadSessionIndices: deadIndices,
            })
          }
        }
      }

      if (dbUpdates.length > 0) {
        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates)
        if (stored > 0) {
          const updatedCheckpointIds = new Set(dbUpdates.map((update) => update.checkpoint_id))
          const touched = missingCheckpoints.filter((cp) =>
            updatedCheckpointIds.has(cp.checkpoint_id),
