// Process a batch of search index messages
export async function processSearchIndexBatch(
  batch: MessageBatch<SearchIndexMessage>,
  env: Env,
): Promise<void> {
  const batchStartTime = Date.now()
  const batchId = generateBatchId()

  const queueWaitTimes = batch.messages.map((msg) => Date.now() - msg.timestamp.getTime())
  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0

  log("batch_started", {
    batchId,
    queue: batch.queue,
    count: batch.messages.length,
    avgQueueWaitMs: avgMs(queueWaitTimes),
    maxQueueWaitMs: maxWaitMs,
  })

  const processingTimes: number[] = []
  let successCount = 0
  let errorCount = 0
  let skippedCount = 0
  let deadLetterCount = 0

  for (const msg of batch.messages) {
    const msgStartTime = Date.now()
    const { repoId, checkpointIds } = msg.body

    // Early return if API keys are missing — don't retry messages that can never succeed
    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
      log("skip_missing_api_keys", {
        batchId,
        repoId,
        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
        hasOpenai: !!env.OPENAI_API_KEY,
      })
      msg.ack()
      skippedCount++
      continue
    }

    let resolvedCheckpointIds: string[] = checkpointIds
    try {
      const db = getBackgroundDb(env)

      const repo = await db.repos.getById(repoId)
      if (!repo) {
        log("skip_repo_not_found", { batchId, repoId })
        msg.ack()
        skippedCount++
        continue
      }

      // When checkpointIds is empty, fetch all checkpoint IDs for this repo
      // and process them in batches. This supports the "reindex all" flow where
      // the endpoint queues one message per repo instead of fetching all IDs upfront.
      resolvedCheckpointIds =
        checkpointIds.length > 0 ? checkpointIds : await getAllCheckpointIdsForRepo(env, repoId)

      if (resolvedCheckpointIds.length === 0) {
        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length })
        msg.ack()
        skippedCount++
        continue
      }

      let totalIndexed = 0

      // Process in batches to avoid large queries and memory pressure
      for (let i = 0; i < resolvedCheckpointIds.length; i += CHECKPOINT_BATCH_SIZE) {
        const batchCheckpointIds = resolvedCheckpointIds.slice(i, i + CHECKPOINT_BATCH_SIZE)
        const indexed = await processCheckpointBatch(
          db,
          env,
          repo,
          repoId,
          batchCheckpointIds,
          batchId,
        )
        totalIndexed += indexed
      }

      const processingMs = Date.now() - msgStartTime
      processingTimes.push(processingMs)

      log("message_processed", {
        batchId,
        repoId,
        requested: resolvedCheckpointIds.length,
        indexed: totalIndexed,
        processingMs,
        attempt: msg.attempts,
      })

      // Log reindex progress when this message is part of an admin-triggered reindex
      if (msg.body.reindexId) {
        log("reindex_progress", {
          reindexId: msg.body.reindexId,
          message: `${(msg.body.reindexMessageIndex ?? 0) + 1}/${msg.body.reindexTotalMessages ?? "?"}`,
          checkpointsInRepo: resolvedCheckpointIds.length,
          checkpointsIndexed: totalIndexed,
          repoId,
        })
      }

      msg.ack()
      successCount++
    } catch (err) {
      const processingMs = Date.now() - msgStartTime
      processingTimes.push(processingMs)
      errorCount++

      const isLastAttempt = msg.attempts > SEARCH_INDEX_MAX_RETRIES

      log("message_error", {
        batchId,
        repoId,
        checkpointCount: resolvedCheckpointIds.length,
        attempt: msg.attempts,
        isLastAttempt,
        processingMs,
        error: err instanceof Error ? err.message : String(err),
      })

      if (isLastAttempt) {
        // Final attempt — store to KV so we can inspect and retry later
        try {
          await storeFailedSearchIndexMessage(env.ENTIRE_CACHE, msg.body, err, msg.attempts)
        } catch (kvErr) {
          log("dead_letter_kv_error", {
            repoId,
            error: kvErr instanceof Error ? kvErr.message : String(kvErr),
          })
        }
        msg.ack()
        deadLetterCount++
      } else {
        // Retry on transient failures (max_retries configured in wrangler.jsonc)
        msg.retry()
      }
    }
  }

  const totalBatchTimeMs = Date.now() - batchStartTime

  log("batch_complete", {
    batchId,
    count: batch.messages.length,
    successCount,
    errorCount,
    skippedCount,
    deadLetterCount,
    totalBatchTimeMs,
    avgProcessingMs: avgMs(processingTimes),
    throughputPerMin:
      totalBatchTimeMs > 0 ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000) : 0,
  })
}

