// ─── KV-backed flag definition cache ─────────────────────────────────────────

export class KVFlagCacheProvider implements FlagDefinitionCacheProvider {
  kv: KVNamespace

  // Stale-while-revalidate: the SDK always reads from cache (fast path).
  // Background revalidation flips this to `true` temporarily so the SDK
  // actually fetches from PostHog when we call `reloadFeatureFlags()`.
  private _allowFetch = false

  constructor(kv: KVNamespace) {
    this.kv = kv
  }

