    // Background revalidation — check actual staleness.
    try {
      const lastFetch = await this.kv.get(KV_LAST_FETCH_KEY)
      if (!lastFetch) return true
      const elapsed = (Date.now() - Number(lastFetch)) / 1000
      return elapsed >= FETCH_INTERVAL_SECONDS
    } catch {
      return true
    }
  }

  /** Check if the cached definitions are stale without triggering a fetch. */
  async needsRefresh(): Promise<boolean> {
    try {
      const lastFetch = await this.kv.get(KV_LAST_FETCH_KEY)
      if (!lastFetch) return true
      const elapsed = (Date.now() - Number(lastFetch)) / 1000
      return elapsed >= FETCH_INTERVAL_SECONDS
    } catch {
      return true
    }
  }

  enableFetch(): void {
    this._allowFetch = true
  }
  disableFetch(): void {
    this._allowFetch = false
  }

  async onFlagDefinitionsReceived(data: FlagDefinitionCacheData): Promise<void> {
    await Promise.all([
      this.kv.put(KV_KEY, JSON.stringify(data)),
      this.kv.put(KV_LAST_FETCH_KEY, String(Date.now())),
