  ENTIRE_CACHE?: KVNamespace
}

export function createPostHogClient(env: PostHogEnv): PostHog | null {
  if (!env.POSTHOG_API_KEY || !env.POSTHOG_PERSONAL_API_KEY) {
    return null
  }

  // Use whichever KV namespace is available (SEARCH_CACHE in search worker, ENTIRE_CACHE in API worker)
  const kvCache = env.SEARCH_CACHE ?? env.ENTIRE_CACHE

  return new PostHog(env.POSTHOG_API_KEY, {
    host: "https://eu.i.posthog.com",
    personalApiKey: env.POSTHOG_PERSONAL_API_KEY,
    enableLocalEvaluation: true,
    featureFlagsPollingInterval: 30000,
    flushAt: 1,
    flushInterval: 0,
    ...(kvCache && {
      flagDefinitionCacheProvider: new KVFlagCacheProvider(kvCache),
    }),
  })
}

// ─── Cached client (reused across requests within the same isolate) ─────────

let cachedClient: PostHog | null = null
let cachedCacheProvider: KVFlagCacheProvider | null = null

/**
 * Get or create a PostHog client that persists across requests in the same
 * CF Worker isolate. The KV binding is updated on each call since Cloudflare
 * provides a fresh env per request.
 */
export function getOrCreatePostHogClient(env: PostHogEnv): PostHog | null {
  if (!env.POSTHOG_API_KEY || !env.POSTHOG_PERSONAL_API_KEY) {
    return null
  }

  const kvCache = env.SEARCH_CACHE ?? env.ENTIRE_CACHE

  if (cachedClient) {
    // Update the KV binding on the existing cache provider
    if (cachedCacheProvider && kvCache) {
      cachedCacheProvider.kv = kvCache
    }
    return cachedClient
  }

  if (kvCache) {
    cachedCacheProvider = new KVFlagCacheProvider(kvCache)
  }

  cachedClient = new PostHog(env.POSTHOG_API_KEY, {
    host: "https://eu.i.posthog.com",
    personalApiKey: env.POSTHOG_PERSONAL_API_KEY,
    enableLocalEvaluation: true,
    featureFlagsPollingInterval: 30000,
    flushAt: 1,
    flushInterval: 0,
    ...(cachedCacheProvider && {
      flagDefinitionCacheProvider: cachedCacheProvider,
    }),
  })

  return cachedClient
}

// ─── Client shutdown helper ─────────────────────────────────────────────────

/**
 * Shutdown the PostHog client to stop polling timers.
 * Call this after flag evaluation is complete to prevent leaked timers in CF Workers.
 */
export async function shutdownPostHogClient(client: PostHog | null): Promise<void> {
  if (!client) return
  try {
    await client.shutdown()
  } catch {
    // Best-effort — don't let shutdown errors affect the request
  }
}

// ─── Background revalidation ────────────────────────────────────────────────

/**
 * Trigger a background refresh of PostHog flag definitions if the KV cache is stale.
 * Designed to be called via `waitUntil()` so it never blocks the response.
 */
export async function revalidateFeatureFlagsIfStale(client: PostHog | null): Promise<void> {
  if (!client || !cachedCacheProvider) return
  try {
    const stale = await cachedCacheProvider.needsRefresh()
    if (!stale) return
    cachedCacheProvider.enableFetch()
    await client.reloadFeatureFlags()
  } catch {
    // Best-effort — don't let revalidation errors affect the request
  } finally {
    cachedCacheProvider?.disableFetch()
  }
}

