/**
 * Evaluate all feature flags for a user (by distinct ID).
 * Used by auth/me to return flags alongside user data for instant client-side rendering.
 *
 * Returns a Record<string, boolean> — empty object on failure or when client is null.
 */
export async function getAllFeatureFlags(
  client: PostHog | null,
  distinctId: string,
  personProperties?: PostHogPersonProperties,
): Promise<Partial<Record<FeatureFlagKey, boolean>>> {
  if (!client) return {}

  try {
    const stringProps: Record<string, string> | undefined = personProperties
      ? Object.fromEntries(
          Object.entries(personProperties)
            .filter(([, v]) => v != null)
            .map(([k, v]) => [k, String(v)]),
        )
      : undefined

    const result = await client.getAllFlags(distinctId, {
      onlyEvaluateLocally: true,
      ...(stringProps && { personProperties: stringProps }),
    })

    const knownFlags = new Set<string>(FEATURE_FLAGS)
    const flags: Partial<Record<FeatureFlagKey, boolean>> = {}
    for (const [key, value] of Object.entries(result)) {
      if (knownFlags.has(key) && (value === true || value === "true")) {
        flags[key as FeatureFlagKey] = true
      }
    }
    return flags
  } catch {
    return {}
  }
}

// ─── Flag evaluation helper ──────────────────────────────────────────────────

/**
 * Evaluate a PostHog feature flag locally.
