export function truncateToBytes(str: string | null, maxBytes: number): string | null {
  if (str === null) return null
  // Fast-path: if all chars are ASCII, length === byte count
  if (str.length <= maxBytes && !/[^\x00-\x7F]/.test(str)) return str
  const encoder = new TextEncoder()
  const encoded = encoder.encode(str)
  if (encoded.length <= maxBytes) return str
  // Walk back from the byte limit until we land on a valid UTF-8 lead byte.
  // This prevents TextDecoder from emitting a U+FFFD replacement character
  // at the truncation boundary, which would corrupt BM25 tokenization.
  let end = maxBytes
  while (end > 0 && (encoded[end]! & 0xc0) === 0x80) end--
  const truncated = encoded.slice(0, end)
  return new TextDecoder().decode(truncated)
}

export function buildSearchText(checkpoint: {
  prompt: string | null
  commit_message: string | null
  files_touched: string[] | null
  transcript?: string | null
  analysis?: string | null
}): string {
  const parts: string[] = []
  if (checkpoint.prompt) {
    parts.push(`Prompt: ${checkpoint.prompt}`)
  }
  if (checkpoint.commit_message) {
    parts.push(`Commit: ${checkpoint.commit_message}`)
  }
  if (checkpoint.files_touched) {
    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`)
  }
  if (checkpoint.transcript) {
    parts.push(`Transcript: ${checkpoint.transcript}`)
  }
  if (checkpoint.analysis) {
    parts.push(`Analysis: ${checkpoint.analysis}`)
  }
  return parts.join("\n")
}

// Retry fetch for OpenAI: retries once on 429 (rate limit) or 5xx with a 500ms backoff.
// 4xx other than 429 are returned immediately (bad request, wrong key, etc.)
async function openAiFetch(url: string, options: RequestInit): Promise<Response> {
  const resp = await fetch(url, options)
  if (resp.ok || (resp.status >= 400 && resp.status < 500 && resp.status !== 429)) {
    return resp // success or non-retryable client error
  }
  // 429 or 5xx — wait and retry once
  await new Promise((r) => setTimeout(r, 500))
  return fetch(url, options)
}

async function embedTextsBatch(openaiApiKey: string, texts: string[]): Promise<number[][]> {
  const resp = await openAiFetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${openaiApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: EMBEDDING_MODEL,
      input: texts,
      dimensions: EMBEDDING_DIMENSIONS,
    }),
  })

  if (!resp.ok) {
    const err = await resp.text().catch(() => "")
    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`)
  }

  const result = (await resp.json()) as {
    data: Array<{ index: number; embedding: number[] }>
  }
  return result.data.sort((a, b) => a.index - b.index).map((item) => item.embedding)
}

async function embedTexts(openaiApiKey: string, texts: string[]): Promise<number[][]> {
  if (texts.length <= EMBED_BATCH_SIZE) {
    return embedTextsBatch(openaiApiKey, texts)
  }
  const allEmbeddings: number[][] = []
  for (let i = 0; i < texts.length; i += EMBED_BATCH_SIZE) {
    const batch = texts.slice(i, i + EMBED_BATCH_SIZE)
    const batchEmbeddings = await embedTextsBatch(openaiApiKey, batch)
    allEmbeddings.push(...batchEmbeddings)
  }
  return allEmbeddings
}

export async function embedQueryVector(openaiApiKey: string, text: string): Promise<number[]> {
  const truncated = text.slice(0, MAX_EMBEDDING_CHARS)
  const resp = await openAiFetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${openaiApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: EMBEDDING_MODEL,
      input: truncated,
      dimensions: EMBEDDING_DIMENSIONS,
    }),
  })

  if (!resp.ok) {
    const err = await resp.text().catch(() => "")
    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`)
  }

  const result = (await resp.json()) as { data: Array<{ embedding: number[] }> }
  return result.data[0].embedding
}

