export async function getSessionsForCheckpoints(
  db: Kysely<DB>,
  repoId: string,
  checkpointIds: string[],
): Promise<Array<{ checkpoint_id: string; sessions: string | null }>> {
  if (checkpointIds.length === 0) return []

  const rows = await db
    .selectFrom("repo_checkpoints")
    .select(["checkpoint_id", "sessions"])
    .where("repo_id", "=", repoId)
    .where("checkpoint_id", "in", checkpointIds)
    .execute()

  // Kysely auto-parses JSON columns; re-stringify for callers that expect a string.
  return rows.map((row) => ({
    checkpoint_id: row.checkpoint_id,
    sessions:
      row.sessions == null
        ? null
        : typeof row.sessions === "string"
          ? row.sessions
          : JSON.stringify(row.sessions),
  }))
}

export async function getHydrationStateForCheckpoints(
  db: Kysely<DB>,
