  const rows = await db
    .selectFrom("repo_checkpoints")
    .select(["checkpoint_id", "payload_hydration_state", "storage_version"])
    .where("repo_id", "=", repoId)
    .where("checkpoint_id", "in", checkpointIds)
    .execute()

  return rows.map((row) => ({
    checkpoint_id: row.checkpoint_id,
    payload_hydration_state: parsePayloadHydrationState(row.payload_hydration_state),
    storage_version: row.storage_version ?? null,
  }))
}

